snmpwrap::Mib& registerMib(snmpwrap::Agent& agent, Instrumentation& impl) {
    snmpwrap::Mib& mib = agent.addMib(oids::root);
    bind(mib, impl);
    return mib;
}

void sendSwtAlarm(snmpwrap::Agent& agent, const std::string& swtName, std::int32_t swtLimit) {
    agent.sendTrap(snmpwrap::Oid{1, 3, 6, 1, 4, 1, 99999, 3, 0, 1},
                   {{snmpwrap::Oid{1, 3, 6, 1, 4, 1, 99999, 1, 1} + snmpwrap::SubId{0}, snmpwrap::Value::string(swtName)},
                    {snmpwrap::Oid{1, 3, 6, 1, 4, 1, 99999, 1, 4} + snmpwrap::SubId{0}, snmpwrap::Value::integer(swtLimit)}});
}

